action.command:
cd /workspace && node -e "
const { createClient } = require('@supabase/supabase-js');
const supabase = createClient(
  process.env.SUPABASE_URL,
  process.env.SUPABASE_SERVICE_ROLE_KEY
);

async function check() {
  // Check source_counts
  const { data: events } = await supabase
    .from('events')
    .select('source, count(*)', { count: 'exact' })
    .eq('status', 'published');

  console.log('Events by source (raw):', JSON.stringify(events, null, 2));

  // Get Kulturhuset count
  const { count: khCount } = await supabase
    .from('events')
    .select('id', { count: 'exact', head: true })
    .eq('source', 'kulturhuset')
    .eq('status', 'published');

  console.log('\\nKulturhuset events count:', khCount);

  // Get sample Kulturhuset events
  const { data: khEvents } = await supabase
    .from('events')
    .select('id, title_en, start_time, source')
    .eq('source', 'kulturhuset')
    .eq('status', 'published')
    .limit(5);

  console.log('\\nSample Kulturhuset events:');
  console.log(JSON.stringify(khEvents, null, 2));
}

check().catch(console.error);
"

